     8→/**
     9→ * 코스메틱 슬롯 종류
    10→ */
    11→UENUM(BlueprintType)
    12→enum class ECosmeticSlot : uint8
    13→{
    14→	None	UMETA(DisplayName = "None"),
    15→	Head	UMETA(DisplayName = "Head"),
    16→	Body	UMETA(DisplayName = "Body"),
    17→	Back	UMETA(DisplayName = "Back"),
    18→	Effect	UMETA(DisplayName = "Effect"),
    19→};
    20→
    21→/**
    22→ * 코스메틱 희귀도
    23→ */
    24→UENUM(BlueprintType)
    25→enum class ECosmeticRarity : uint8
    26→{
    27→	Common		UMETA(DisplayName = "Common"),
    28→	Uncommon	UMETA(DisplayName = "Uncommon"),
    29→	Rare		UMETA(DisplayName = "Rare"),
    30→	Epic		UMETA(DisplayName = "Epic"),
    31→	Legendary	UMETA(DisplayName = "Legendary"),
    32→};
    33→
    34→/**
    35→ * 개별 코스메틱 아이템 인스턴스 (인벤토리에 보유한 아이템)
    36→ * FName ItemId를 중간 키로 사용하여 플랫폼 독립적 식별
    37→ */
    38→USTRUCT(BlueprintType)
    39→struct WJWORLD_API FCosmeticItemInstance
    40→{
    41→	GENERATED_BODY()
    42→
    43→	FCosmeticItemInstance() = default;
    44→
    45→	explicit FCosmeticItemInstance(FName InItemId)
    46→		: ItemId(InItemId)
    47→	{
    48→	}
    49→
    50→	/** 플랫폼 독립적 아이템 식별자 (DataAsset과 매핑) */
    51→	UPROPERTY(EditAnywhere, BlueprintReadWrite)
    52→	FName ItemId;
    53→
    54→	/** 보유 수량 */
    55→	UPROPERTY(EditAnywhere, BlueprintReadWrite)
    56→	int32 Quantity = 1;
    57→
    58→	bool IsValid() const { return !ItemId.IsNone(); }
    59→
    60→	bool operator==(const FCosmeticItemInstance& Other) const
    61→	{
    62→		return ItemId == Other.ItemId;
    63→	}
    64→
    65→	friend uint32 GetTypeHash(const FCosmeticItemInstance& Instance)
    66→	{
    67→		return GetTypeHash(Instance.ItemId);
    68→	}
    69→};
    70→
    71→/**
    72→ * 코스메틱 슬롯-아이템 매핑 엔트리 (리플리케이션 가능)
    73→ */
    74→USTRUCT(BlueprintType)
    75→struct WJWORLD_API FCosmeticSlotEntry
    76→{
    77→	GENERATED_BODY()
    78→
    79→	FCosmeticSlotEntry() = default;
    80→
    81→	FCosmeticSlotEntry(ECosmeticSlot InSlot, FName InItemId)
    82→		: Slot(InSlot), ItemId(InItemId)
    83→	{
    84→	}
    85→
    86→	UPROPERTY(EditAnywhere, BlueprintReadWrite)
    87→	ECosmeticSlot Slot = ECosmeticSlot::None;
    88→
    89→	UPROPERTY(EditAnywhere, BlueprintReadWrite)
    90→	FName ItemId;
    91→
    92→	bool operator==(const FCosmeticSlotEntry& Other) const
    93→	{
    94→		return Slot == Other.Slot && ItemId == Other.ItemId;
    95→	}
    96→
    97→	bool operator!=(const FCosmeticSlotEntry& Other) const
    98→	{
    99→		return !(*this == Other);
   100→	}
   101→};
   102→
   103→/**
   104→ * 코스메틱 로드아웃 (장착 중인 슬롯 → 아이템 매핑)
   105→ * TArray<FCosmeticSlotEntry> 기반으로 리플리케이션 지원
   106→ */
   107→USTRUCT(BlueprintType)
   108→struct WJWORLD_API FCosmeticLoadout
   109→{
   110→	GENERATED_BODY()
   111→
   112→	/** 슬롯별 장착 아이템 목록 */
   113→	UPROPERTY(EditAnywhere, BlueprintReadWrite)
   114→	TArray<FCosmeticSlotEntry> Entries;
   115→
   116→	/** 특정 슬롯에 아이템 장착 */
   117→	void Equip(ECosmeticSlot Slot, FName ItemId)
   118→	{
   119→		if (Slot == ECosmeticSlot::None || ItemId.IsNone())
   120→		{
   121→			return;
   122→		}
   123→
   124→		// 이미 해당 슬롯에 엔트리가 있으면 교체
   125→		for (FCosmeticSlotEntry& Entry : Entries)
   126→		{
   127→			if (Entry.Slot == Slot)
   128→			{
   129→				Entry.ItemId = ItemId;
   130→				return;
   131→			}
   132→		}
   133→
   134→		Entries.Emplace(Slot, ItemId);
   135→	}
   136→
   137→	/** 특정 슬롯의 아이템 해제 */
   138→	void Unequip(ECosmeticSlot Slot)
   139→	{
   140→		Entries.RemoveAll([Slot](const FCosmeticSlotEntry& Entry)
   141→		{
   142→			return Entry.Slot == Slot;
   143→		});
   144→	}
   145→
   146→	/** 특정 슬롯에 장착된 아이템 반환 */
   147→	FName GetEquippedItem(ECosmeticSlot Slot) const
   148→	{
   149→		for (const FCosmeticSlotEntry& Entry : Entries)
   150→		{
   151→			if (Entry.Slot == Slot)
   152→			{
   153→				return Entry.ItemId;
   154→			}
   155→		}
   156→		return NAME_None;
   157→	}
   158→
   159→	/** 로드아웃이 비었는지 확인 */
   160→	bool IsEmpty() const
   161→	{
   162→		return Entries.Num() == 0;
   163→	}
   164→
   165→	/** 모든 슬롯의 키 배열 반환 */
   166→	TArray<ECosmeticSlot> GetEquippedSlots() const
   167→	{
   168→		TArray<ECosmeticSlot> Slots;
   169→		Slots.Reserve(Entries.Num());
   170→		for (const FCosmeticSlotEntry& Entry : Entries)
   171→		{
   172→			Slots.Add(Entry.Slot);
   173→		}
   174→		return Slots;
   175→	}
   176→
   177→	/** 초기화 */
   178→	void Reset()
   179→	{
   180→		Entries.Reset();
   181→	}
   182→
   183→	bool operator==(const FCosmeticLoadout& Other) const
   184→	{
   185→		if (Entries.Num() != Other.Entries.Num())
   186→		{
   187→			return false;
   188→		}
   189→
   190→		for (const FCosmeticSlotEntry& Entry : Entries)
   191→		{
   192→			if (Other.GetEquippedItem(Entry.Slot) != Entry.ItemId)
   193→			{
   194→				return false;
   195→			}
   196→		}
   197→		return true;
   198→	}
   199→
   200→	bool operator!=(const FCosmeticLoadout& Other) const
   201→	{
   202→		return !(*this == Other);
   203→	}
   204→};
   205→

