     6→const FCosmeticItemDefinition* UWjWorldCosmeticCatalogDataAsset::FindByItemId(FName ItemId) const
     7→{
     8→	BuildLookupMaps();
     9→
    10→	if (const int32* Index = ItemIdToIndex.Find(ItemId))
    11→	{
    12→		return &Items[*Index];
    13→	}
    14→	return nullptr;
    15→}
    16→
    17→const FCosmeticItemDefinition* UWjWorldCosmeticCatalogDataAsset::FindBySteamItemDefId(int32 SteamItemDefId) const
    18→{
    19→	BuildLookupMaps();
    20→
    21→	if (const int32* Index = SteamDefIdToIndex.Find(SteamItemDefId))
    22→	{
    23→		return &Items[*Index];
    24→	}
    25→	return nullptr;
    26→}
    27→
    28→FName UWjWorldCosmeticCatalogDataAsset::SteamItemDefIdToItemId(int32 SteamItemDefId) const
    29→{
    30→	if (const FCosmeticItemDefinition* Def = FindBySteamItemDefId(SteamItemDefId))
    31→	{
    32→		return Def->ItemId;
    33→	}
    34→	return NAME_None;
    35→}
    36→
    37→int32 UWjWorldCosmeticCatalogDataAsset::ItemIdToSteamItemDefId(FName ItemId) const
    38→{
    39→	if (const FCosmeticItemDefinition* Def = FindByItemId(ItemId))
    40→	{
    41→		return Def->SteamItemDefId;
    42→	}
    43→	return 0;
    44→}
    45→
    46→TArray<const FCosmeticItemDefinition*> UWjWorldCosmeticCatalogDataAsset::GetItemsBySlot(ECosmeticSlot Slot) const
    47→{
    48→	TArray<const FCosmeticItemDefinition*> Result;
    49→	for (const FCosmeticItemDefinition& Item : Items)
    50→	{
    51→		if (Item.Slot == Slot)
    52→		{
    53→			Result.Add(&Item);
    54→		}
    55→	}
    56→	return Result;
    57→}
