   102→void UWjWorldCosmeticCatalogDataAsset::BuildLookupMaps() const
   103→{
   104→	if (!bLookupDirty)
   105→	{
   106→		return;
   107→	}
   108→
   109→	ItemIdToIndex.Reset();
   110→	SteamDefIdToIndex.Reset();
   111→
   112→	for (int32 i = 0; i < Items.Num(); ++i)
   113→	{
   114→		const FCosmeticItemDefinition& Item = Items[i];
   115→		if (!Item.ItemId.IsNone())
   116→		{
   117→			ItemIdToIndex.Add(Item.ItemId, i);
   118→		}
   119→		if (Item.SteamItemDefId != 0)
   120→		{
   121→			SteamDefIdToIndex.Add(Item.SteamItemDefId, i);
   122→		}
   123→	}
   124→
   125→	bLookupDirty = false;
   126→}
