    52→		TabBackButton->OnClicked.AddDynamic(this, &UCosmeticMainWindow::OnTabBackClicked);
    53→	}
    54→
    55→	if (TabEffectButton)
    56→	{
    57→		TabEffectButton->OnClicked.RemoveDynamic(this, &UCosmeticMainWindow::OnTabEffectClicked);
    58→		TabEffectButton->OnClicked.AddDynamic(this, &UCosmeticMainWindow::OnTabEffectClicked);
    59→	}
    60→
    61→	// 액션/닫기 버튼 바인딩
    62→	if (ActionButton)
