    77→		GemChargeButton->OnClicked.RemoveDynamic(this, &UCosmeticMainWindow::OnGemChargeClicked);
    78→		GemChargeButton->OnClicked.AddDynamic(this, &UCosmeticMainWindow::OnGemChargeClicked);
    79→	}
    80→
    81→	// CurrencyBalanceWidget의 Gem 영역 클릭 구독
