   122→void UCosmeticMainWindow::NativeDestruct()
   123→{
   124→	// 알림 타이머 정리
   125→	if (UWorld* World = GetWorld())
   126→	{
   127→		World->GetTimerManager().ClearTimer(NotificationTimerHandle);
   128→	}
   129→
   130→	// Gem 관련 델리게이트 해제
   131→	if (GemChargeButton)
   132→	{
   133→		GemChargeButton->OnClicked.RemoveDynamic(this, &UCosmeticMainWindow::OnGemChargeClicked);
   134→	}
   135→
   136→	if (CurrencyBalanceWidget)
   137→	{
   138→		CurrencyBalanceWidget->OnGemAreaClicked.RemoveDynamic(this, &UCosmeticMainWindow::OnGemAreaClicked);
   139→	}
   140→
   141→	// 서브시스템 델리게이트 바인딩 해제
   142→	UGameInstance* GI = GetGameInstance();
   143→	if (GI)
   144→	{
   145→		if (UWjWorldCosmeticSubsystem* CosmeticSub = GI->GetSubsystem<UWjWorldCosmeticSubsystem>())
   146→		{
   147→			CosmeticSub->OnInventoryUpdated.RemoveDynamic(this, &UCosmeticMainWindow::OnInventoryUpdated);
   148→			CosmeticSub->OnLoadoutChanged.RemoveDynamic(this, &UCosmeticMainWindow::OnLoadoutChanged);
   149→		}
   150→
   151→		if (UWjWorldPurchaseSubsystem* PurchaseSub = GI->GetSubsystem<UWjWorldPurchaseSubsystem>())
   152→		{
   153→			PurchaseSub->OnPurchaseComplete.RemoveDynamic(this, &UCosmeticMainWindow::OnPurchaseComplete);
   154→		}
   155→
   156→		if (UWjWorldCurrencySubsystem* CurrencySub = GI->GetSubsystem<UWjWorldCurrencySubsystem>())
   157→		{
   158→			CurrencySub->OnCurrencyPurchaseComplete.RemoveDynamic(this, &UCosmeticMainWindow::OnCurrencyPurchaseComplete);
   159→		}
   160→	}
   161→
   162→	ClearItemGrid();
   163→	Super::NativeDestruct();
   164→}
