   166→void UCosmeticMainWindow::ShowPopup()
   167→{
   168→	AddToViewport(100);
   169→
   170→	// 입력 모드: UI 전용
   171→	APlayerController* PC = GetWorld()->GetFirstPlayerController();
   172→	if (PC)
   173→	{
   174→		FInputModeUIOnly InputMode;
   175→		InputMode.SetLockMouseToViewportBehavior(EMouseLockMode::DoNotLock);
   176→		PC->SetInputMode(InputMode);
   177→		PC->bShowMouseCursor = true;
   178→	}
   179→
   180→	// 초기 상태 설정 및 UI 갱신
   181→	CurrentMode = ECosmeticWindowMode::Shop;
   182→	CurrentSlot = ECosmeticSlot::Head;
   183→	SelectedItemId = NAME_None;
   184→
   185→	RefreshUI();
   186→
   187→	UE_LOG(LogWjWorldCosmetic, Log, TEXT("CosmeticMainWindow: Popup shown"));
   188→}
