   190→void UCosmeticMainWindow::ClosePopup()
   191→{
   192→	// 시착 취소
   193→	if (PreviewPanel)
   194→	{
   195→		PreviewPanel->ResetPreview();
   196→	}
   197→
   198→	RemoveFromParent();
   199→
   200→	// 입력 모드 복원
   201→	APlayerController* PC = GetWorld()->GetFirstPlayerController();
   202→	if (PC)
   203→	{
   204→		PC->SetInputMode(FInputModeGameAndUI());
   205→		PC->bShowMouseCursor = true;
   206→	}
   207→
   208→	UE_LOG(LogWjWorldCosmetic, Log, TEXT("CosmeticMainWindow: Popup closed"));
   209→}
