   241→void UCosmeticMainWindow::OnActionButtonClicked()
   242→{
   243→	if (SelectedItemId.IsNone())
   244→	{
   245→		return;
   246→	}
   247→
   248→	UGameInstance* GI = GetGameInstance();
   249→	if (!GI)
   250→	{
   251→		return;
   252→	}
   253→
   254→	UWjWorldCosmeticSubsystem* CosmeticSub = GI->GetSubsystem<UWjWorldCosmeticSubsystem>();
   255→	if (!CosmeticSub)
   256→	{
   257→		return;
   258→	}
   259→
   260→	const FCosmeticLoadout& Loadout = CosmeticSub->GetLoadout();
   261→	FName EquippedItem = Loadout.GetEquippedItem(CurrentSlot);
   262→
   263→	if (CurrentMode == ECosmeticWindowMode::Shop)
   264→	{
   265→		// 상점 모드
   266→		if (CosmeticSub->HasItem(SelectedItemId))
   267→		{
   268→			// 보유 중인 아이템 → 장착 또는 해제
   269→			if (EquippedItem == SelectedItemId)
   270→			{
   271→				CosmeticSub->UnequipSlot(CurrentSlot);
   272→				UE_LOG(LogWjWorldCosmetic, Log, TEXT("CosmeticMainWindow: Unequipped slot %d (from Shop)"), static_cast<int32>(CurrentSlot));
   273→			}
   274→			else
   275→			{
   276→				CosmeticSub->EquipItem(CurrentSlot, SelectedItemId);
   277→				UE_LOG(LogWjWorldCosmetic, Log, TEXT("CosmeticMainWindow: Equipped %s on slot %d (from Shop)"), *SelectedItemId.ToString(), static_cast<int32>(CurrentSlot));
   278→			}
   279→			CosmeticSub->SaveLoadoutToLocal();
   280→		}
   281→		else
   282→		{
   283→			// 미보유 아이템 → 재화 구매 우선, 재화 가격 없는 경우만 Steam 실결제
   284→			UWjWorldCurrencySubsystem* CurrencySub = GI->GetSubsystem<UWjWorldCurrencySubsystem>();
   285→
   286→			// 재화 교환 진행 중이면 중복 요청 방지
   287→			if (CurrencySub && CurrencySub->IsExchangePending())
   288→			{
   289→				UE_LOG(LogWjWorldCosmetic, Log, TEXT("CosmeticMainWindow: Exchange already pending, ignoring click"));
   290→				return;
   291→			}
   292→
   293→			const FCosmeticItemDefinition* ItemDef = CosmeticSub->GetCatalog() ? CosmeticSub->GetCatalog()->FindByItemId(SelectedItemId) : nullptr;
   294→
   295→			bool bHasCurrencyPrice = ItemDef && (ItemDef->CoinPrice > 0 || ItemDef->GemPrice > 0);
   296→			bool bCurrencyPurchased = false;
   297→
   298→			if (ItemDef && CurrencySub)
   299→			{
   300→				// Coin 잔액 충분 시 Coin으로 구매
   301→				if (ItemDef->CoinPrice > 0 && CurrencySub->GetBalance(ECurrencyType::Coin) >= ItemDef->CoinPrice)
   302→				{
   303→					bCurrencyPurchased = CurrencySub->PurchaseItemWithCurrency(SelectedItemId, ECurrencyType::Coin);
   304→					if (bCurrencyPurchased)
   305→					{
   306→						UE_LOG(LogWjWorldCosmetic, Log, TEXT("CosmeticMainWindow: Coin purchase requested for %s"), *SelectedItemId.ToString());
   307→					}
   308→				}
   309→
   310→				// Coin 구매 실패 시 Gem 잔액 충분하면 Gem으로 구매
   311→				if (!bCurrencyPurchased && ItemDef->GemPrice > 0 && CurrencySub->GetBalance(ECurrencyType::Gem) >= ItemDef->GemPrice)
   312→				{
   313→					bCurrencyPurchased = CurrencySub->PurchaseItemWithCurrency(SelectedItemId, ECurrencyType::Gem);
   314→					if (bCurrencyPurchased)
   315→					{
   316→						UE_LOG(LogWjWorldCosmetic, Log, TEXT("CosmeticMainWindow: Gem purchase requested for %s"), *SelectedItemId.ToString());
   317→					}
   318→				}
   319→			}
   320→
   321→			if (bCurrencyPurchased)
   322→			{
   323→				// 재화 구매 성공 → 알림은 OnCurrencyPurchaseComplete에서 처리
   324→			}
   325→			else if (bHasCurrencyPrice)
   326→			{
   327→				// 재화 가격이 있지만 잔액 부족 → Steam 실결제로 넘어가지 않음
   328→				ShowNotification(NSLOCTEXT("Cosmetic", "InsufficientBalanceNotify", "잔액이 부족합니다"), false);
   329→				UE_LOG(LogWjWorldCosmetic, Log, TEXT("CosmeticMainWindow: Insufficient balance for %s"), *SelectedItemId.ToString());
   330→			}
   331→			else
   332→			{
   333→				// 재화 가격 없음 → Steam 실결제
   334→				UWjWorldPurchaseSubsystem* PurchaseSub = GI->GetSubsystem<UWjWorldPurchaseSubsystem>();
   335→				if (PurchaseSub && !PurchaseSub->IsPurchasePending())
   336→				{
   337→					PurchaseSub->RequestPurchase(SelectedItemId);
   338→					UE_LOG(LogWjWorldCosmetic, Log, TEXT("CosmeticMainWindow: Steam purchase requested for %s"), *SelectedItemId.ToString());
   339→				}
   340→			}
   341→		}
   342→	}
   343→	else
   344→	{
   345→		// 인벤토리 모드: 장착 또는 해제
   346→		if (EquippedItem == SelectedItemId)
   347→		{
   348→			CosmeticSub->UnequipSlot(CurrentSlot);
   349→			UE_LOG(LogWjWorldCosmetic, Log, TEXT("CosmeticMainWindow: Unequipped slot %d"), static_cast<int32>(CurrentSlot));
   350→		}
   351→		else
   352→		{
   353→			CosmeticSub->EquipItem(CurrentSlot, SelectedItemId);
   354→			UE_LOG(LogWjWorldCosmetic, Log, TEXT("CosmeticMainWindow: Equipped %s on slot %d"), *SelectedItemId.ToString(), static_cast<int32>(CurrentSlot));
   355→		}
   356→		CosmeticSub->SaveLoadoutToLocal();
   357→	}
   358→}
