   549→void UCosmeticMainWindow::RefreshActionButton()
   550→{
   551→	if (!ActionButton || !ActionButtonText)
   552→	{
   553→		return;
   554→	}
   555→
   556→	if (SelectedItemId.IsNone())
   557→	{
   558→		ActionButton->SetIsEnabled(false);
   559→		ActionButtonText->SetText(NSLOCTEXT("Cosmetic", "SelectItem", "아이템 선택"));
   560→		return;
   561→	}
   562→
   563→	UGameInstance* GI = GetGameInstance();
   564→	if (!GI)
   565→	{
   566→		return;
   567→	}
   568→
   569→	UWjWorldCosmeticSubsystem* CosmeticSub = GI->GetSubsystem<UWjWorldCosmeticSubsystem>();
   570→	if (!CosmeticSub)
   571→	{
   572→		return;
   573→	}
   574→
   575→	const FCosmeticLoadout& Loadout = CosmeticSub->GetLoadout();
   576→	FName EquippedItem = Loadout.GetEquippedItem(CurrentSlot);
   577→	bool bIsEquipped = (EquippedItem == SelectedItemId);
   578→
   579→	// 장착/해제 분기에서 기본 색상 리셋
   580→	auto ResetButtonTextColor = [this]()
   581→	{
   582→		ActionButtonText->SetColorAndOpacity(FSlateColor(FLinearColor::White));
   583→	};
   584→
   585→	if (CurrentMode == ECosmeticWindowMode::Shop)
   586→	{
   587→		// 상점 모드
   588→		if (CosmeticSub->HasItem(SelectedItemId))
   589→		{
   590→			// 보유 중인 아이템 → 장착/해제 가능
   591→			ActionButton->SetIsEnabled(true);
   592→			ResetButtonTextColor();
   593→
   594→			if (bIsEquipped)
   595→			{
   596→				ActionButtonText->SetText(NSLOCTEXT("Cosmetic", "Unequip", "해제"));
   597→			}
   598→			else
   599→			{
   600→				ActionButtonText->SetText(NSLOCTEXT("Cosmetic", "Equip", "장착"));
   601→			}
   602→		}
   603→		else
   604→		{
   605→			// 미보유 아이템 → 구매
   606→			UWjWorldPurchaseSubsystem* PurchaseSub = GI->GetSubsystem<UWjWorldPurchaseSubsystem>();
   607→			UWjWorldCurrencySubsystem* CurrencySub2 = GI->GetSubsystem<UWjWorldCurrencySubsystem>();
   608→			bool bPending = (PurchaseSub && PurchaseSub->IsPurchasePending())
   609→				|| (CurrencySub2 && CurrencySub2->IsExchangePending());
   610→
   611→			const FCosmeticItemDefinition* ItemDef = nullptr;
   612→			if (CosmeticSub->GetCatalog())
   613→			{
   614→				ItemDef = CosmeticSub->GetCatalog()->FindByItemId(SelectedItemId);
   615→			}
   616→
   617→			UWjWorldCurrencySubsystem* CurrencySub = GI->GetSubsystem<UWjWorldCurrencySubsystem>();
   618→
   619→			bool bHasCoinPrice = ItemDef && ItemDef->CoinPrice > 0;
   620→			bool bHasGemPrice = ItemDef && ItemDef->GemPrice > 0;
   621→			bool bCoinAffordable = bHasCoinPrice && CurrencySub && CurrencySub->GetBalance(ECurrencyType::Coin) >= ItemDef->CoinPrice;
   622→			bool bGemAffordable = bHasGemPrice && CurrencySub && CurrencySub->GetBalance(ECurrencyType::Gem) >= ItemDef->GemPrice;
   623→
   624→			if (bPending)
   625→			{
   626→				ActionButton->SetIsEnabled(false);
   627→				ResetButtonTextColor();
   628→				ActionButtonText->SetText(NSLOCTEXT("Cosmetic", "Purchasing", "구매 중..."));
   629→			}
   630→			else if (bCoinAffordable)
   631→			{
   632→				ActionButton->SetIsEnabled(true);
   633→				ResetButtonTextColor();
   634→				ActionButtonText->SetText(FText::Format(
   635→					NSLOCTEXT("Cosmetic", "PurchaseCoinAmount", "{0} Coin 구매"),
   636→					FText::AsNumber(ItemDef->CoinPrice)));
   637→			}
   638→			else if (bGemAffordable)
   639→			{
   640→				ActionButton->SetIsEnabled(true);
   641→				ResetButtonTextColor();
   642→				ActionButtonText->SetText(FText::Format(
   643→					NSLOCTEXT("Cosmetic", "PurchaseGemAmount", "{0} Gem 구매"),
   644→					FText::AsNumber(ItemDef->GemPrice)));
   645→			}
   646→			else if (bHasCoinPrice || bHasGemPrice)
   647→			{
   648→				// 재화 가격이 있지만 잔액 부족
   649→				ActionButton->SetIsEnabled(false);
   650→				ActionButtonText->SetColorAndOpacity(FSlateColor(FLinearColor::Red));
   651→				ActionButtonText->SetText(NSLOCTEXT("Cosmetic", "InsufficientBalance", "잔액 부족"));
   652→			}
   653→			else
   654→			{
   655→				// 재화 가격 없음 → Steam 실결제
   656→				ActionButton->SetIsEnabled(true);
   657→				ResetButtonTextColor();
   658→				ActionButtonText->SetText(NSLOCTEXT("Cosmetic", "Purchase", "구매"));
   659→			}
   660→		}
   661→	}
   662→	else
   663→	{
   664→		// 인벤토리 모드
   665→		ActionButton->SetIsEnabled(true);
   666→		ResetButtonTextColor();
   667→
   668→		if (bIsEquipped)
   669→		{
   670→			ActionButtonText->SetText(NSLOCTEXT("Cosmetic", "Unequip", "해제"));
   671→		}
   672→		else
   673→		{
   674→			ActionButtonText->SetText(NSLOCTEXT("Cosmetic", "Equip", "장착"));
   675→		}
   676→	}
   677→}
