   806→void UCosmeticMainWindow::PopulateInventoryItems()
   807→{
   808→	UGameInstance* GI = GetGameInstance();
   809→	if (!GI)
   810→	{
   811→		return;
   812→	}
   813→
   814→	UWjWorldCosmeticSubsystem* CosmeticSub = GI->GetSubsystem<UWjWorldCosmeticSubsystem>();
   815→	if (!CosmeticSub || !CosmeticSub->GetCatalog())
   816→	{
   817→		return;
   818→	}
   819→
   820→	UWjWorldCosmeticCatalogDataAsset* Catalog = CosmeticSub->GetCatalog();
   821→	const TArray<FCosmeticItemInstance>& Inventory = CosmeticSub->GetInventory();
   822→	const FCosmeticLoadout& Loadout = CosmeticSub->GetLoadout();
   823→
   824→	int32 Index = 0;
   825→	for (const FCosmeticItemInstance& ItemInstance : Inventory)
   826→	{
   827→		const FCosmeticItemDefinition* ItemDef = Catalog->FindByItemId(ItemInstance.ItemId);
   828→		if (!ItemDef || !ItemDef->IsValid())
   829→		{
   830→			continue;
   831→		}
   832→
   833→		// 현재 슬롯에 해당하는 아이템만 표시
   834→		if (ItemDef->Slot != CurrentSlot)
   835→		{
   836→			continue;
   837→		}
   838→
   839→		UCosmeticItemEntryWidget* EntryWidget = CreateItemEntry(*ItemDef);
   840→		if (!EntryWidget)
   841→		{
   842→			continue;
   843→		}
   844→
   845→		// 인벤토리 모드에서는 항상 보유 중
   846→		bool bEquipped = Loadout.GetEquippedItem(CurrentSlot) == ItemDef->ItemId;
   847→
   848→		EntryWidget->SetOwned(true);
   849→		EntryWidget->SetEquipped(bEquipped);
   850→		EntryWidget->SetSelected(ItemDef->ItemId == SelectedItemId);
   851→
   852→		// 그리드에 추가
   853→		if (ItemGridPanel)
   854→		{
   855→			ItemGridPanel->AddChildToUniformGrid(EntryWidget, Index / GridColumnCount, Index % GridColumnCount);
   856→		}
   857→
   858→		ItemEntryWidgets.Add(EntryWidget);
   859→		Index++;
   860→	}
   861→
   862→	UE_LOG(LogWjWorldCosmetic, Log, TEXT("CosmeticMainWindow: Populated %d inventory items"), Index);
   863→}
