    17→void UWjWorldCosmeticComponent::BeginPlay()
    18→{
    19→	Super::BeginPlay();
    20→
    21→	BackupDefaultMeshes();
    22→
    23→	// CosmeticSubsystem 구독 및 초기화
    24→	if (UGameInstance* GI = GetWorld()->GetGameInstance())
    25→	{
    26→		if (UWjWorldCosmeticSubsystem* CosmeticSub = GI->GetSubsystem<UWjWorldCosmeticSubsystem>())
    27→		{
    28→			// 카탈로그 설정 (모든 캐릭터)
    29→			SetCatalog(CosmeticSub->GetCatalog());
    30→
    31→			// 로컬 플레이어만 델리게이트 구독 및 초기 로드아웃 적용
    32→			// 3자 캐릭터는 OnRep_PlayerState() → OnPawnSet() 경로로 PlayerState의 로드아웃 적용
    33→			APawn* OwnerPawn = Cast<APawn>(GetOwner());
    34→			if (OwnerPawn && OwnerPawn->IsLocallyControlled())
    35→			{
    36→				CosmeticSub->OnLoadoutChanged.AddDynamic(this, &ThisClass::OnLoadoutChangedHandler);
    37→				ApplyLoadout(CosmeticSub->GetLoadout());
    38→				UE_LOG(LogWjWorldCosmetic, Log, TEXT("CosmeticComponent: 로컬 플레이어 초기화 완료"));
    39→			}
    40→			else
    41→			{
    42→				UE_LOG(LogWjWorldCosmetic, Log, TEXT("CosmeticComponent: 3자 캐릭터 - PlayerState 리플리케이션 대기"));
    43→			}
    44→		}
    45→	}
    46→}
