    77→void UWjWorldCosmeticComponent::ApplyLoadout(const FCosmeticLoadout& InLoadout)
    78→{
    79→	APawn* OwnerPawn = Cast<APawn>(GetOwner());
    80→	FString OwnerName = OwnerPawn ? OwnerPawn->GetName() : TEXT("Unknown");
    81→	bool bIsLocal = OwnerPawn ? OwnerPawn->IsLocallyControlled() : false;
    82→
    83→	UE_LOG(LogWjWorldCosmetic, Log, TEXT("CosmeticComponent::ApplyLoadout - Owner: %s, IsLocal: %d, Entries: %d"),
    84→		*OwnerName, bIsLocal, InLoadout.Entries.Num());
    85→
    86→	// 기존 코스메틱 제거
    87→	ClearAll();
    88→
    89→	// 새 로드아웃 적용
    90→	for (const FCosmeticSlotEntry& Entry : InLoadout.Entries)
    91→	{
    92→		UE_LOG(LogWjWorldCosmetic, Log, TEXT("  - Applying Slot %d: %s"),
    93→			static_cast<int32>(Entry.Slot), *Entry.ItemId.ToString());
    94→		ApplySlot(Entry.Slot, Entry.ItemId);
    95→	}
    96→}
