   113→void UWjWorldCosmeticSubsystem::GrantItemLocally(FName ItemId, int32 Quantity)
   114→{
   115→	if (ItemId.IsNone() || Quantity <= 0)
   116→	{
   117→		return;
   118→	}
   119→
   120→	// 기존 아이템 수량 증가 또는 새로 추가
   121→	FCosmeticItemInstance* Existing = CachedInventory.FindByPredicate([ItemId](const FCosmeticItemInstance& Inst)
   122→	{
   123→		return Inst.ItemId == ItemId;
   124→	});
   125→
   126→	if (Existing)
   127→	{
   128→		Existing->Quantity += Quantity;
   129→	}
   130→	else
   131→	{
   132→		FCosmeticItemInstance NewItem(ItemId);
   133→		NewItem.Quantity = Quantity;
   134→		CachedInventory.Add(NewItem);
   135→	}
   136→
   137→	UE_LOG(LogWjWorldCosmetic, Log, TEXT("로컬 아이템 부여: %s x%d"), *ItemId.ToString(), Quantity);
   138→	OnInventoryUpdated.Broadcast();
   139→}
