   141→bool UWjWorldCosmeticSubsystem::EquipItem(ECosmeticSlot Slot, FName ItemId)
   142→{
   143→	if (Slot == ECosmeticSlot::None)
   144→	{
   145→		UE_LOG(LogWjWorldCosmetic, Warning, TEXT("None 슬롯에 장착할 수 없습니다."));
   146→		return false;
   147→	}
   148→
   149→	if (!HasItem(ItemId))
   150→	{
   151→		UE_LOG(LogWjWorldCosmetic, Warning, TEXT("아이템 '%s'을 보유하고 있지 않습니다."), *ItemId.ToString());
   152→		return false;
   153→	}
   154→
   155→	// 카탈로그 검증: 슬롯 일치 확인
   156→	if (Catalog)
   157→	{
   158→		const FCosmeticItemDefinition* Def = Catalog->FindByItemId(ItemId);
   159→		if (Def && Def->Slot != Slot)
   160→		{
   161→			UE_LOG(LogWjWorldCosmetic, Warning, TEXT("아이템 '%s'은 슬롯 %d에 장착할 수 없습니다 (정의된 슬롯: %d)."),
   162→				*ItemId.ToString(), static_cast<int32>(Slot), static_cast<int32>(Def->Slot));
   163→			return false;
   164→		}
   165→	}
   166→
   167→	CurrentLoadout.Equip(Slot, ItemId);
   168→	SaveLoadoutToLocal();
   169→	OnLoadoutChanged.Broadcast(Slot, ItemId);
   170→
   171→	UE_LOG(LogWjWorldCosmetic, Log, TEXT("장착: 슬롯 %d ← %s"), static_cast<int32>(Slot), *ItemId.ToString());
   172→	return true;
   173→}
