   196→void UWjWorldCosmeticSubsystem::LoadLoadoutFromLocal()
   197→{
   198→	CurrentLoadout.Reset();
   199→
   200→	for (int32 SlotIdx = static_cast<int32>(ECosmeticSlot::Head);
   201→		SlotIdx <= static_cast<int32>(ECosmeticSlot::Effect); ++SlotIdx)
   202→	{
   203→		FString SlotKey = FString::Printf(TEXT("Slot_%d"), SlotIdx);
   204→		FString ItemIdStr;
   205→		if (GConfig->GetString(*LoadoutConfigSection, *SlotKey, ItemIdStr, GGameUserSettingsIni))
   206→		{
   207→			if (!ItemIdStr.IsEmpty())
   208→			{
   209→				CurrentLoadout.Equip(static_cast<ECosmeticSlot>(SlotIdx), FName(*ItemIdStr));
