   249→void UWjWorldCosmeticSubsystem::PollSteamInventoryResult()
   250→{
   251→#if WITH_STEAM
   252→	if (PendingResultHandle == k_SteamInventoryResultInvalid)
   253→	{
   254→		StopInventoryPolling();
   255→		return;
   256→	}
   257→
   258→	ISteamInventory* SteamInv = SteamInventory();
   259→	if (!SteamInv)
   260→	{
   261→		StopInventoryPolling();
   262→		return;
   263→	}
   264→
   265→	EResult Status = SteamInv->GetResultStatus(PendingResultHandle);
   266→
   267→	if (Status == k_EResultPending)
   268→	{
   269→		// 아직 대기 중 - 계속 폴링
   270→		return;
   271→	}
   272→
   273→	// 결과 처리
   274→	if (Status == k_EResultOK)
   275→	{
   276→		UE_LOG(LogWjWorldCosmetic, Log, TEXT("Steam 인벤토리 결과 수신 성공"));
   277→		ParseInventoryResult();
   278→	}
   279→	else
   280→	{
   281→		UE_LOG(LogWjWorldCosmetic, Warning, TEXT("Steam 인벤토리 결과 실패 (Status: %d)"), static_cast<int32>(Status));
   282→	}
   283→
   284→	// 정리
   285→	SteamInv->DestroyResult(PendingResultHandle);
   286→	PendingResultHandle = k_SteamInventoryResultInvalid;
   287→	StopInventoryPolling();
   288→
   289→	// 델리게이트 브로드캐스트
   290→	OnInventoryUpdated.Broadcast();
   291→#else
   292→	StopInventoryPolling();
   293→#endif
   294→}
