   302→void UWjWorldCosmeticSubsystem::ParseInventoryResult()
   303→{
   304→#if WITH_STEAM
   305→	ISteamInventory* SteamInv = SteamInventory();
   306→	if (!SteamInv)
   307→	{
   308→		UE_LOG(LogWjWorldCosmetic, Warning, TEXT("ParseInventoryResult: SteamInventory 없음"));
   309→		return;
   310→	}
   311→
   312→	if (PendingResultHandle == k_SteamInventoryResultInvalid)
   313→	{
   314→		return;
   315→	}
   316→
   317→	// 아이템 개수 확인
   318→	uint32 ItemCount = 0;
   319→	if (!SteamInv->GetResultItems(PendingResultHandle, nullptr, &ItemCount) || ItemCount == 0)
   320→	{
   321→		UE_LOG(LogWjWorldCosmetic, Log, TEXT("Steam 인벤토리: 아이템 0개"));
   322→		CachedInventory.Empty();
   323→		AllItemQuantities.Empty();
   324→		return;
   325→	}
   326→
   327→	// 아이템 상세 정보 가져오기
   328→	TArray<SteamItemDetails_t> ItemDetails;
   329→	ItemDetails.SetNum(ItemCount);
   330→
   331→	if (!SteamInv->GetResultItems(PendingResultHandle, ItemDetails.GetData(), &ItemCount))
   332→	{
   333→		UE_LOG(LogWjWorldCosmetic, Warning, TEXT("Steam 인벤토리 아이템 상세 정보 가져오기 실패"));
   334→		return;
   335→	}
   336→
   337→	// 전체 DefId별 수량 + 인스턴스 ID 캐시 갱신 (재화 잔액/ExchangeItems + 배치 소유권)
   338→	AllItemQuantities.Empty();
   339→	AllItemInstanceIds.Empty();
   340→	for (uint32 i = 0; i < ItemCount; ++i)
   341→	{
   342→		const SteamItemDetails_t& Details = ItemDetails[i];
   343→		if (Details.m_unQuantity > 0)
   344→		{
   345→			AllItemQuantities.FindOrAdd(Details.m_iDefinition) += Details.m_unQuantity;
   346→
   347→			// 첫 번째 인스턴스 ID만 저장 (재화 ExchangeItems용)
   348→			if (!AllItemInstanceIds.Contains(Details.m_iDefinition))
   349→			{
   350→				AllItemInstanceIds.Add(Details.m_iDefinition, Details.m_itemId);
   351→			}
   352→		}
   353→	}
   354→
   355→	// 캐시된 코스메틱 인벤토리 갱신 (Catalog 필요)
   356→	CachedInventory.Empty(ItemCount);
   357→
   358→	if (!Catalog)
   359→	{
   360→		UE_LOG(LogWjWorldCosmetic, Warning, TEXT("ParseInventoryResult: Catalog 없음 — 전체 수량만 캐싱"));
   361→		return;
   362→	}
   363→
   364→	for (uint32 i = 0; i < ItemCount; ++i)
   365→	{
   366→		const SteamItemDetails_t& Details = ItemDetails[i];
   367→
   368→		// 수량 체크 (0이면 소비됨/만료됨)
   369→		if (Details.m_unQuantity == 0)
   370→		{
   371→			continue;
   372→		}
   373→
   374→		// SteamItemDefId → ItemId 변환
   375→		FName ItemId = Catalog->SteamItemDefIdToItemId(Details.m_iDefinition);
   376→		if (ItemId.IsNone())
   377→		{
   378→			// 코스메틱 카탈로그에 없는 아이템 — 전체 수량 캐시에는 이미 기록됨
   379→			continue;
   380→		}
   381→
   382→		// 기존 아이템 수량 증가 또는 새로 추가
   383→		FCosmeticItemInstance* Existing = CachedInventory.FindByPredicate([ItemId](const FCosmeticItemInstance& Inst)
   384→		{
   385→			return Inst.ItemId == ItemId;
   386→		});
   387→
   388→		if (Existing)
   389→		{
   390→			Existing->Quantity += Details.m_unQuantity;
   391→		}
   392→		else
   393→		{
   394→			FCosmeticItemInstance NewItem(ItemId);
   395→			NewItem.Quantity = Details.m_unQuantity;
   396→			CachedInventory.Add(NewItem);
   397→		}
   398→
   399→		UE_LOG(LogWjWorldCosmetic, Verbose, TEXT("인벤토리 아이템: %s (DefId: %d, Qty: %d)"),
   400→			*ItemId.ToString(), Details.m_iDefinition, Details.m_unQuantity);
   401→	}
   402→
   403→	UE_LOG(LogWjWorldCosmetic, Log, TEXT("Steam 인벤토리 파싱 완료: %d개 코스메틱 아이템, %d개 전체 DefId"),
   404→		CachedInventory.Num(), AllItemQuantities.Num());
   405→#endif
   406→}
