   408→void UWjWorldCosmeticSubsystem::LoadPlacementInventoryFromLocal()
   409→{
   410→#if !WITH_STEAM
   411→	// 비Steam 환경: GConfig에서 배치 오브젝트 소유 수량 로드
   412→	static const FString PlacementInventorySection = TEXT("PlacementInventory");
   413→
   414→	TArray<FString> Keys;
   415→	GConfig->GetSection(*PlacementInventorySection, Keys, GGameUserSettingsIni);
   416→
   417→	for (const FString& KeyValuePair : Keys)
   418→	{
   419→		FString Key, Value;
   420→		if (KeyValuePair.Split(TEXT("="), &Key, &Value))
   421→		{
   422→			int32 Quantity = FCString::Atoi(*Value);
   423→			if (Quantity > 0)
   424→			{
   425→				// ObjectId에 해당하는 SteamItemDefId를 찾아서 AllItemQuantities에 기록
   426→				// DeveloperSettings의 카탈로그에서 검색
   427→				const UWjWorldDeveloperSettings* Settings = GetDefault<UWjWorldDeveloperSettings>();
   428→				if (Settings)
   429→				{
   430→					UWjWorldPlaceableObjectDataAsset* PlacementCatalog = Settings->GetPlaceableCatalogForContext(EPlacementContext::Lobby);
   431→					if (PlacementCatalog)
   432→					{
   433→						const FPlaceableObjectDefinition* Def = PlacementCatalog->FindByObjectId(FName(*Key));
   434→						if (Def && Def->SteamItemDefId > 0)
   435→						{
   436→							AllItemQuantities.FindOrAdd(Def->SteamItemDefId) += Quantity;
   437→						}
   438→					}
   439→				}
   440→			}
   441→		}
   442→	}
   443→
   444→	UE_LOG(LogWjWorldCosmetic, Log, TEXT("비Steam 배치 인벤토리 로드 완료 (%d DefIds)"), AllItemQuantities.Num());
   445→#endif
   446→}
