   448→bool UWjWorldCosmeticSubsystem::AddPromoItem(int32 SteamItemDefId)
   449→{
   450→#if WITH_STEAM
   451→	ISteamInventory* SteamInv = SteamInventory();
   452→	if (!SteamInv)
   453→	{
   454→		UE_LOG(LogWjWorldCosmetic, Warning, TEXT("AddPromoItem: Steam Inventory API 사용 불가"));
   455→		return false;
   456→	}
   457→
   458→	SteamItemDef_t ItemDef = static_cast<SteamItemDef_t>(SteamItemDefId);
   459→	SteamInventoryResult_t ResultHandle = k_SteamInventoryResultInvalid;
   460→
   461→	if (SteamInv->AddPromoItem(&ResultHandle, ItemDef))
   462→	{
   463→		UE_LOG(LogWjWorldCosmetic, Log, TEXT("AddPromoItem: 프로모 아이템 지급 요청 성공 (DefId: %d)"), SteamItemDefId);
   464→
   465→		// 결과 핸들 정리 (비동기 결과는 나중에 인벤토리 갱신으로 확인)
   466→		SteamInv->DestroyResult(ResultHandle);
   467→
   468→		// 인벤토리 갱신 요청
   469→		RequestInventoryRefresh();
   470→		return true;
