   127→void UCosmeticPreviewPanel::CreatePreviewActor()
   128→{
   129→	if (PreviewActor)
   130→	{
   131→		return;
   132→	}
   133→
   134→	UWorld* World = GetWorld();
   135→	if (!World)
   136→	{
   137→		return;
   138→	}
   139→
   140→	// 프리뷰 액터 클래스가 설정되지 않은 경우 기본 클래스 사용
   141→	TSubclassOf<ACharacterPreviewActor> ActorClass = PreviewActorClass;
   142→	if (!ActorClass)
   143→	{
   144→		ActorClass = ACharacterPreviewActor::StaticClass();
   145→	}
   146→
   147→	// 월드 밖 위치에 스폰 (화면에 보이지 않음)
   148→	FVector SpawnLocation(0.f, 0.f, 15000.f);
   149→	FActorSpawnParameters SpawnParams;
   150→	SpawnParams.SpawnCollisionHandlingOverride = ESpawnActorCollisionHandlingMethod::AlwaysSpawn;
   151→
   152→	PreviewActor = World->SpawnActor<ACharacterPreviewActor>(ActorClass, SpawnLocation, FRotator::ZeroRotator, SpawnParams);
   153→
   154→	if (PreviewActor)
   155→	{
   156→		// 로컬 플레이어의 Pawn에서 SkeletalMesh와 AnimBlueprint 복사
   157→		APlayerController* PC = GetOwningPlayer();
   158→		if (PC && PC->GetPawn())
   159→		{
   160→			PreviewActor->SetupFromPawn(PC->GetPawn());
   161→		}
   162→
   163→		UE_LOG(LogWjWorldCosmetic, Log, TEXT("CosmeticPreviewPanel: PreviewActor created"));
   164→	}
   165→}
