   150→void UWjWorldPurchaseSubsystem::StartPurchasePolling()
   151→{
   152→	UWorld* World = GetWorld();
   153→	if (!World)
   154→	{
   155→		return;
   156→	}
   157→
   158→	// 1초 간격으로 구매 결과 폴링
   159→	World->GetTimerManager().SetTimer(
   160→		PurchasePollTimerHandle,
   161→		this,
   162→		&UWjWorldPurchaseSubsystem::PollPurchaseResult,
   163→		1.0f,
   164→		true
   165→	);
   166→
   167→	UE_LOG(LogWjWorldCosmetic, Log, TEXT("구매 결과 폴링 시작"));
   168→}
   169→
   170→void UWjWorldPurchaseSubsystem::StopPurchasePolling()
   171→{
   172→	UWorld* World = GetWorld();
   173→	if (World)
   174→	{
   175→		World->GetTimerManager().ClearTimer(PurchasePollTimerHandle);
   176→	}
   177→
   178→	UE_LOG(LogWjWorldCosmetic, Log, TEXT("구매 결과 폴링 중지"));
   179→}
   180→
   181→void UWjWorldPurchaseSubsystem::PollPurchaseResult()
   182→{
   183→#if WITH_STEAM
   184→	if (CurrentState != EPurchaseState::Pending)
   185→	{
   186→		StopPurchasePolling();
   187→		return;
   188→	}
   189→
   190→	// 타임아웃 체크
   191→	UWorld* World = GetWorld();
   192→	if (World)
   193→	{
   194→		float ElapsedTime = World->GetTimeSeconds() - PurchaseStartTime;
   195→		if (ElapsedTime > PurchaseTimeoutSeconds)
   196→		{
   197→			UE_LOG(LogWjWorldCosmetic, Warning, TEXT("구매 타임아웃 (%.1f초 경과)"), ElapsedTime);
   198→			HandlePurchaseResult(false);
   199→			return;
   200→		}
   201→	}
   202→
   203→	// Steam 콜백이 아닌 인벤토리 변경 체크 방식 사용
   204→	// Steam은 구매 완료 시 자동으로 인벤토리에 아이템을 추가하므로,
   205→	// 주기적으로 인벤토리를 확인하여 아이템이 추가되었는지 체크
   206→	ISteamInventory* SteamInv = SteamInventory();
   207→	if (!SteamInv)
   208→	{
   209→		HandlePurchaseResult(false);
   210→		return;
   211→	}
   212→
   213→	// 인벤토리 갱신 요청을 통해 구매 완료 여부 확인
   214→	// (실제 콜백은 CosmeticSubsystem에서 처리)
   215→	UWjWorldCosmeticSubsystem* CosmeticSub = GetGameInstance()->GetSubsystem<UWjWorldCosmeticSubsystem>();
   216→	if (CosmeticSub && CosmeticSub->HasItem(PendingItemId))
   217→	{
   218→		// 이미 아이템을 보유하고 있으면 구매 성공
   219→		UE_LOG(LogWjWorldCosmetic, Log, TEXT("구매 확인: 아이템 '%s' 보유 감지"), *PendingItemId.ToString());
   220→		HandlePurchaseResult(true);
   221→	}
   222→#else
   223→	StopPurchasePolling();
   224→#endif
   225→}
