   155→FLinearColor UCosmeticItemEntryWidget::GetRarityColor(ECosmeticRarity Rarity) const
   156→{
   157→	switch (Rarity)
   158→	{
   159→	case ECosmeticRarity::Common:
   160→		return FLinearColor(0.5f, 0.5f, 0.5f, 1.f); // 회색
   161→	case ECosmeticRarity::Uncommon:
   162→		return FLinearColor(0.2f, 0.8f, 0.2f, 1.f); // 녹색
   163→	case ECosmeticRarity::Rare:
   164→		return FLinearColor(0.2f, 0.4f, 1.f, 1.f);  // 파랑
   165→	case ECosmeticRarity::Epic:
   166→		return FLinearColor(0.6f, 0.2f, 0.8f, 1.f); // 보라
   167→	case ECosmeticRarity::Legendary:
   168→		return FLinearColor(1.f, 0.6f, 0.f, 1.f);   // 주황
   169→	default:
   170→		return FLinearColor::White;
   171→	}
   172→}
