   174→void UCosmeticItemEntryWidget::OnIconLoaded()
   175→{
   176→	if (!IconLoadHandle.IsValid() || !IconLoadHandle->HasLoadCompleted())
   177→	{
   178→		return;
   179→	}
   180→
   181→	UObject* LoadedAsset = IconLoadHandle->GetLoadedAsset();
   182→	if (UTexture2D* IconTexture = Cast<UTexture2D>(LoadedAsset))
   183→	{
   184→		if (IconImage)
   185→		{
   186→			IconImage->SetBrushFromTexture(IconTexture);
   187→			IconImage->SetColorAndOpacity(FLinearColor::White);
   188→		}
   189→	}
   190→
   191→	IconLoadHandle.Reset();
   192→}
