    79→void AWjWorldPlayerStateBase::OnCosmeticLoadoutUpdated()
    80→{
    81→	// 소유 Pawn 찾기
    82→	APawn* OwnerPawn = GetPawn();
    83→
    84→	// GetPawn()이 null인 경우 (3자 캐릭터), World에서 이 PlayerState를 사용하는 Character 찾기
    85→	if (!OwnerPawn)
    86→	{
    87→		UWorld* World = GetWorld();
    88→		if (World)
    89→		{
    90→			for (TActorIterator<ACharacter> It(World); It; ++It)
    91→			{
    92→				if (It->GetPlayerState() == this)
    93→				{
    94→					OwnerPawn = *It;
    95→					UE_LOG(LogWjWorldCosmetic, Log, TEXT("PlayerStateBase: 3자 캐릭터 발견 (%s)"), *GetPlayerName());
    96→					break;
    97→				}
    98→			}
    99→		}
   100→	}
   101→
   102→	// CosmeticComponent에 로드아웃 적용
   103→	if (OwnerPawn)
   104→	{
   105→		if (UWjWorldCosmeticComponent* CosmeticComp = OwnerPawn->FindComponentByClass<UWjWorldCosmeticComponent>())
   106→		{
   107→			CosmeticComp->ApplyLoadout(CosmeticLoadout);
   108→			UE_LOG(LogWjWorldCosmetic, Log, TEXT("PlayerStateBase: 코스메틱 로드아웃 적용 (%s)"), *GetPlayerName());
   109→		}
   110→		bPendingCosmeticApply = false;
   111→	}
   112→	else
   113→	{
   114→		// Pawn이 아직 없으면 대기 플래그 설정
   115→		bPendingCosmeticApply = true;
   116→		UE_LOG(LogWjWorldCosmetic, Log, TEXT("PlayerStateBase: Pawn 없음, 코스메틱 적용 대기 (%s)"), *GetPlayerName());
   117→	}
   118→}
   119→
   120→void AWjWorldPlayerStateBase::OnPawnSet(APawn* OldPawn, APawn* NewPawn)
   121→{
   122→	// 코스메틱 로드아웃 적용 (로컬 플레이어 + 3자 캐릭터 모두)
   123→	// 3자 캐릭터는 BeginPlay()에서 초기 로드아웃을 적용하지 않으므로 여기서 적용
   124→	if (NewPawn)
   125→	{
   126→		if (UWjWorldCosmeticComponent* CosmeticComp = NewPawn->FindComponentByClass<UWjWorldCosmeticComponent>())
   127→		{
   128→			// 로드아웃이 있으면 적용
   129→			if (!CosmeticLoadout.Entries.IsEmpty())
   130→			{
   131→				CosmeticComp->ApplyLoadout(CosmeticLoadout);
   132→				UE_LOG(LogWjWorldCosmetic, Log, TEXT("PlayerStateBase: 코스메틱 적용 완료 (%s, %d entries)"),
   133→					*GetPlayerName(), CosmeticLoadout.Entries.Num());
   134→			}
   135→		}
   136→		bPendingCosmeticApply = false;
   137→	}
   138→}
