    70→void UPlayerProfileWidget::ShowPlayerProfile(const FUniqueNetIdRepl& PlayerId,
    71→	const FText& PlayerName,
    72→	const FCosmeticLoadout& Loadout)
    73→{
    74→	// 플레이어 이름
    75→	if (PlayerNameText)
    76→	{
    77→		PlayerNameText->SetText(PlayerName);
    78→	}
    79→
    80→	// 3D 프리뷰
    81→	CreatePreviewActor(Loadout);
    82→
    83→	// 스탯 조회
    84→	UGameInstance* GI = GetGameInstance();
    85→	if (!GI)
    86→	{
    87→		SetVisibility(ESlateVisibility::Visible);
    88→		return;
    89→	}
    90→
    91→	UWjWorldStatsSubsystem* StatsSub = GI->GetSubsystem<UWjWorldStatsSubsystem>();
    92→	if (!StatsSub)
    93→	{
    94→		SetVisibility(ESlateVisibility::Visible);
    95→		return;
    96→	}
    97→
    98→	FString PlayerIdStr = PlayerId.ToString();
    99→	if (!PlayerId.IsValid() || PlayerIdStr.IsEmpty())
   100→	{
   101→		// UniqueId가 없는 경우 (LAN/NULL 서브시스템) — 스탯 표시 불가
   102→		if (StatsContainer)
   103→		{
   104→			StatsContainer->ClearChildren();
   105→			UTextBlock* UnavailableText = NewObject<UTextBlock>(this);
   106→			UnavailableText->SetText(NSLOCTEXT("WjWorldProfile", "StatsUnavailable", "Stats unavailable"));
   107→			StatsContainer->AddChild(UnavailableText);
   108→		}
   109→	}
   110→	else if (StatsSub->IsUserStatsReadyByString(PlayerIdStr))
   111→	{
   112→		PopulateUserStats(PlayerIdStr);
   113→	}
   114→	else
