   267→void UPlayerProfileWidget::CreatePreviewActor(const FCosmeticLoadout& Loadout)
   268→{
   269→	DestroyPreviewActor();
   270→
   271→	UWorld* World = GetWorld();
   272→	if (!World)
   273→	{
   274→		return;
   275→	}
   276→
   277→	FActorSpawnParameters SpawnParams;
   278→	SpawnParams.SpawnCollisionHandlingOverride = ESpawnActorCollisionHandlingMethod::AlwaysSpawn;
   279→
   280→	// 월드에서 보이지 않는 위치에 스폰
   281→	FVector SpawnLocation(0.f, 0.f, 15000.f);
   282→	PreviewActor = World->SpawnActor<ACharacterPreviewActor>(ACharacterPreviewActor::StaticClass(), SpawnLocation, FRotator::ZeroRotator, SpawnParams);
   283→
   284→	if (PreviewActor)
   285→	{
   286→		// 기본 캐릭터 메시 설정 (모든 캐릭터가 같은 base mesh 사용)
   287→		APlayerController* PC = GetOwningPlayer();
   288→		if (PC && PC->GetPawn())
   289→		{
   290→			PreviewActor->SetupFromPawn(PC->GetPawn());
   291→		}
   292→
   293→		PreviewActor->SetupPreview(Loadout);
   294→
   295→		// 실시간 캡처이므로 즉시 렌더 타겟 적용 (코스메틱 로드되는 대로 자동 반영)
   296→		ApplyRenderTargetToImage();
   297→	}
   298→}
