    98→void UWjWorldCosmeticComponent::ApplySlot(ECosmeticSlot Slot, FName ItemId)
    99→{
   100→	if (Slot == ECosmeticSlot::None || ItemId.IsNone())
   101→	{
   102→		return;
   103→	}
   104→
   105→	if (!Catalog)
   106→	{
   107→		UE_LOG(LogWjWorldCosmetic, Warning, TEXT("카탈로그가 설정되지 않았습니다."));
   108→		return;
   109→	}
   110→
   111→	const FCosmeticItemDefinition* Def = Catalog->FindByItemId(ItemId);
   112→	if (!Def)
   113→	{
   114→		UE_LOG(LogWjWorldCosmetic, Warning, TEXT("카탈로그에서 아이템 '%s'을 찾을 수 없습니다."), *ItemId.ToString());
   115→		return;
   116→	}
   117→
   118→	// 기존 핸들 취소
   119→	if (TSharedPtr<FStreamableHandle>* ExistingHandle = ActiveStreamHandles.Find(Slot))
   120→	{
   121→		if (ExistingHandle->IsValid())
   122→		{
   123→			(*ExistingHandle)->CancelHandle();
   124→		}
   125→	}
   126→
   127→	AppliedLoadout.Equip(Slot, ItemId);
   128→
   129→	// 비동기 에셋 로드
   130→	TArray<FSoftObjectPath> AssetsToLoad;
   131→
   132→	if (!Def->SkeletalMesh.IsNull())
   133→	{
   134→		AssetsToLoad.Add(Def->SkeletalMesh.ToSoftObjectPath());
   135→	}
   136→	if (!Def->StaticMesh.IsNull())
   137→	{
   138→		AssetsToLoad.Add(Def->StaticMesh.ToSoftObjectPath());
   139→	}
   140→
   141→	if (AssetsToLoad.Num() > 0)
   142→	{
   143→		TSharedPtr<FStreamableHandle> Handle = StreamableManager.RequestAsyncLoad(
   144→			AssetsToLoad,
   145→			FStreamableDelegate::CreateUObject(this, &ThisClass::OnAssetLoaded, Slot, ItemId)
   146→		);
   147→		ActiveStreamHandles.Add(Slot, Handle);
   148→
   149→		UE_LOG(LogWjWorldCosmetic, Log, TEXT("비동기 로드 시작: 슬롯 %d ← %s (%d 에셋)"),
   150→			static_cast<int32>(Slot), *ItemId.ToString(), AssetsToLoad.Num());
   151→	}
   152→}
   153→
   154→void UWjWorldCosmeticComponent::ClearSlot(ECosmeticSlot Slot)
   155→{
   156→	// 비동기 핸들 취소
   157→	if (TSharedPtr<FStreamableHandle>* Handle = ActiveStreamHandles.Find(Slot))
   158→	{
   159→		if (Handle->IsValid())
   160→		{
   161→			(*Handle)->CancelHandle();
   162→		}
   163→		ActiveStreamHandles.Remove(Slot);
   164→	}
   165→
   166→	AppliedLoadout.Unequip(Slot);
   167→	RestoreDefaultMesh(Slot);
   168→
   169→	// 동적 메시 컴포넌트 제거
   170→	if (TObjectPtr<UMeshComponent>* MeshComp = SlotMeshComponents.Find(Slot))
   171→	{
   172→		if (*MeshComp)
   173→		{
   174→			(*MeshComp)->DestroyComponent();
   175→		}
   176→		SlotMeshComponents.Remove(Slot);
   177→	}
   178→}
