   214→void AWjWorldCharacterBase::SetupInputBindings(UInputComponent* PlayerInputComponent)
   215→{
   216→	UEnhancedInputComponent* EnhancedInputComponent = Cast<UEnhancedInputComponent>(PlayerInputComponent);
   217→	const FString AbilityInputAction = TEXT("Ability");
   218→
   219→	UInputMappingContext* IMC = GetDefaultMappingContext();
   220→
   221→	if (EnhancedInputComponent && IMC)
   222→	{
   223→		TSet<FString> AlreadyBoundActions;
   224→		const TArray<FEnhancedActionKeyMapping>& Mappings = IMC->GetMappings();
   225→
   226→		for (const auto& Mapping : Mappings)
   227→		{
   228→			if (!Mapping.Action)
   229→			{
   230→				continue;
   231→			}
   232→
   233→			FString ActionName = Mapping.Action.GetName();
   234→			ActionName.RemoveFromStart(TEXT("IA_"));
   235→
   236→			// TriggerEvent별로 함수 찾기
   237→			TArray<TPair<ETriggerEvent, FString>> EventSuffixes = {
   238→				{ETriggerEvent::Started, TEXT("_Started")},
   239→				{ETriggerEvent::Ongoing, TEXT("_Ongoing")},
   240→				{ETriggerEvent::Canceled, TEXT("_Canceled")},
   241→				{ETriggerEvent::Completed, TEXT("_Completed")},
   242→				{ETriggerEvent::Triggered, TEXT("")} // 기본 (접미사 없음)
   243→			};
   244→
   245→			if (ActionName.Contains(AbilityInputAction))
   246→			{
   247→				ActionName.RemoveFromStart(AbilityInputAction);
   248→				int32 Param1 = FCString::Atoi(*ActionName);
   249→
   250→				EnhancedInputComponent->BindAction(Mapping.Action, ETriggerEvent::Started, this, &AWjWorldCharacterBase::GasInputPressed, Param1);
   251→				EnhancedInputComponent->BindAction(Mapping.Action, ETriggerEvent::Completed, this, &AWjWorldCharacterBase::GasInputReleased, Param1);
   252→			}
   253→			else
   254→			{
   255→				for (const auto& EventSuffix : EventSuffixes)
   256→				{
   257→					FString FunctionName = ActionName + EventSuffix.Value;
   258→
   259→					if (AlreadyBoundActions.Contains(FunctionName))
   260→					{
   261→						continue;
   262→					}
   263→
   264→					UFunction* Function = FindFunction(FName(*FunctionName));
   265→					if (Function)
   266→					{
   267→						EnhancedInputComponent->BindAction(Mapping.Action, EventSuffix.Key, this, FName(*FunctionName));
   268→						AlreadyBoundActions.Add(FunctionName);
   269→
   270→						// 접미사 있는 바인딩 존재 시 접미사 없는(Triggered) 바인딩 차단
   271→						// 예: Jump_Started 존재 시 ACharacter::Jump() 중복 바인딩 방지
   272→						if (!EventSuffix.Value.IsEmpty())
   273→						{
   274→							AlreadyBoundActions.Add(ActionName);
   275→						}
   276→					}
   277→				}
   278→			}
   279→		}
   280→	}
   281→}
