   293→void AWjWorldCharacterBase::Move(const FInputActionValue& Value)
   294→{
   295→	const FVector2D MoveVector = Value.Get<FVector2D>();
   296→	
   297→	if (Controller == nullptr || MoveVector.Length() <= 0.0f)
   298→	{
   299→		return;
   300→	}
   301→	
   302→	if (CameraMode == WjWorldGameplayTag::Camera_ThirdPerson())
   303→	{
   304→		APlayerController* PC = GetController<APlayerController>();
   305→		if (PC && PC->PlayerCameraManager)
   306→		{
   307→			//FRotator CameraRotation = PC->PlayerCameraManager->GetCameraRotation();
   308→			FRotator CameraRotation = GamePlayCamera->GetEvaluatedCameraRotation();
   309→
   310→			const FRotator YawRotation(0.0f, CameraRotation.Yaw, 0.0f);
   311→
   312→			const FVector ForwardDirection = FRotationMatrix(YawRotation).GetUnitAxis(EAxis::X);
   313→			const FVector RightDirection = FRotationMatrix(YawRotation).GetUnitAxis(EAxis::Y);
   314→
   315→			AddMovementInput(ForwardDirection, MoveVector.Y);
   316→			AddMovementInput(RightDirection, MoveVector.X);
   317→		}
   318→	}
   319→	else if (CameraMode == WjWorldGameplayTag::Camera_FirstPerson())
   320→	{
   321→		const FRotator ControlRotation = GetActorRotation();
   322→		const FRotator YawRotation(0.0f, ControlRotation.Yaw, 0.0f);
   323→
   324→		const FVector ForwardDirection = FRotationMatrix(YawRotation).GetUnitAxis(EAxis::X);
   325→		const FVector RightDirection = FRotationMatrix(YawRotation).GetUnitAxis(EAxis::Y);
   326→
   327→		AddMovementInput(ForwardDirection, MoveVector.Y);
   328→		AddMovementInput(RightDirection, MoveVector.X);
   329→	}
   330→	else if (CameraMode == WjWorldGameplayTag::Camera_TopDown())
   331→	{
   332→		// TopDown: 월드 좌표계 기준으로 이동
   333→		// 카메라가 회전해도 WASD는 항상 월드 방향 기준
   334→		const FRotator YawRotation(0.0f, 0.0f, 0.0f); // 월드 좌표계
   335→
   336→		const FVector ForwardDirection = FRotationMatrix(YawRotation).GetUnitAxis(EAxis::X); // (1, 0, 0)
   337→		const FVector RightDirection = FRotationMatrix(YawRotation).GetUnitAxis(EAxis::Y);   // (0, 1, 0)
   338→
   339→		AddMovementInput(ForwardDirection, MoveVector.Y); // W/S
   340→		AddMovementInput(RightDirection, MoveVector.X);   // D/A
   341→	}
   342→}
