   191→
   192→void UWjWorldCosmeticComponent::OnAssetLoaded(ECosmeticSlot Slot, FName ItemId)
   193→{
   194→	if (!IsValid(this) || !GetOwner())
   195→	{
   196→		return;
   197→	}
   198→
   199→	// 로드 완료 시 해당 슬롯이 여전히 같은 아이템인지 확인
   200→	FName CurrentItem = AppliedLoadout.GetEquippedItem(Slot);
   201→	if (CurrentItem != ItemId)
   202→	{
   203→		UE_LOG(LogWjWorldCosmetic, Log, TEXT("비동기 로드 완료되었으나 슬롯이 변경됨 (기대: %s, 현재: %s)"),
   204→			*ItemId.ToString(), *CurrentItem.ToString());
   205→		return;
   206→	}
   207→
   208→	if (!Catalog)
   209→	{
   210→		return;
   211→	}
   212→
   213→	const FCosmeticItemDefinition* Def = Catalog->FindByItemId(ItemId);
   214→	if (!Def)
   215→	{
   216→		return;
   217→	}
   218→
   219→	ACharacter* OwnerCharacter = Cast<ACharacter>(GetOwner());
   220→	if (!OwnerCharacter)
   221→	{
   222→		return;
   223→	}
   224→
   225→	// 소켓 이름 결정 (아이템 정의 우선, 없으면 슬롯 기본값)
   226→	FName SocketName = Def->AttachSocketName.IsNone() ? GetDefaultSocketName(Slot) : Def->AttachSocketName;
   227→
   228→	// SkeletalMesh 적용 (Head, Body 슬롯)
   229→	if (!Def->SkeletalMesh.IsNull() && Def->SkeletalMesh.IsValid())
   230→	{
   231→		USkeletalMesh* LoadedMesh = Def->SkeletalMesh.Get();
   232→		if (LoadedMesh)
   233→		{
   234→			// Body 슬롯: 캐릭터의 메인 메시 교체
   235→			if (Slot == ECosmeticSlot::Body)
   236→			{
   237→				USkeletalMeshComponent* MeshComp = OwnerCharacter->GetMesh();
   238→				if (MeshComp)
   239→				{
   240→					MeshComp->SetSkeletalMesh(LoadedMesh);
   241→					UE_LOG(LogWjWorldCosmetic, Log, TEXT("Body 메시 적용: %s"), *LoadedMesh->GetName());
   242→				}
   243→			}
   244→			else
   245→			{
   246→				// 다른 슬롯: 소켓에 부착
   247→				USkeletalMeshComponent* SlotMesh = NewObject<USkeletalMeshComponent>(OwnerCharacter);
   248→				SlotMesh->SetSkeletalMesh(LoadedMesh);
   249→				SlotMesh->AttachToComponent(
   250→					OwnerCharacter->GetMesh(),
   251→					FAttachmentTransformRules::SnapToTargetNotIncludingScale,
   252→					SocketName
   253→				);
   254→
   255→				// 오프셋 적용
   256→				SlotMesh->SetRelativeLocation(Def->AttachLocationOffset);
   257→				SlotMesh->SetRelativeRotation(Def->AttachRotationOffset);
   258→				SlotMesh->SetRelativeScale3D(Def->AttachScale);
   259→
   260→				SlotMesh->RegisterComponent();
   261→				SlotMeshComponents.Add(Slot, SlotMesh);
   262→
   263→				UE_LOG(LogWjWorldCosmetic, Log, TEXT("슬롯 %d 메시 소켓 부착: %s → %s"),
   264→					static_cast<int32>(Slot), *LoadedMesh->GetName(), *SocketName.ToString());
   265→			}
   266→		}
   267→	}
   268→
   269→	// StaticMesh 적용 (Back, Effect 슬롯)
   270→	if (!Def->StaticMesh.IsNull() && Def->StaticMesh.IsValid())
   271→	{
   272→		UStaticMesh* LoadedStaticMesh = Def->StaticMesh.Get();
   273→		if (LoadedStaticMesh)
   274→		{
   275→			UStaticMeshComponent* SlotStaticMesh = NewObject<UStaticMeshComponent>(OwnerCharacter);
   276→			SlotStaticMesh->SetStaticMesh(LoadedStaticMesh);
   277→			SlotStaticMesh->AttachToComponent(
   278→				OwnerCharacter->GetMesh(),
   279→				FAttachmentTransformRules::SnapToTargetNotIncludingScale,
   280→				SocketName
   281→			);
   282→
   283→			// 오프셋 적용
   284→			SlotStaticMesh->SetRelativeLocation(Def->AttachLocationOffset);
   285→			SlotStaticMesh->SetRelativeRotation(Def->AttachRotationOffset);
   286→			SlotStaticMesh->SetRelativeScale3D(Def->AttachScale);
   287→
   288→			SlotStaticMesh->RegisterComponent();
   289→			SlotMeshComponents.Add(Slot, SlotStaticMesh);
   290→
   291→			UE_LOG(LogWjWorldCosmetic, Log, TEXT("슬롯 %d 스태틱 메시 소켓 부착: %s → %s"),
   292→				static_cast<int32>(Slot), *LoadedStaticMesh->GetName(), *SocketName.ToString());
   293→		}
   294→	}
   295→
   296→	// 로드 핸들 정리
   297→	ActiveStreamHandles.Remove(Slot);
   298→}
   299→
   300→UMeshComponent* UWjWorldCosmeticComponent::GetOrCreateSlotMeshComponent(ECosmeticSlot Slot)
   301→{
   302→	if (TObjectPtr<UMeshComponent>* Found = SlotMeshComponents.Find(Slot))
   303→	{
   304→		return *Found;
   305→	}
   306→	return nullptr;
   307→}
   308→
   309→void UWjWorldCosmeticComponent::BackupDefaultMeshes()
   310→{
   311→	if (bDefaultMeshesBackedUp)
   312→	{
   313→		return;
   314→	}
   315→
   316→	ACharacter* OwnerCharacter = Cast<ACharacter>(GetOwner());
   317→	if (!OwnerCharacter)
   318→	{
   319→		return;
   320→	}
   321→
   322→	USkeletalMeshComponent* MeshComp = OwnerCharacter->GetMesh();
   323→	if (MeshComp && MeshComp->GetSkeletalMeshAsset())
   324→	{
   325→		DefaultMeshes.Add(ECosmeticSlot::Body, MeshComp->GetSkeletalMeshAsset());
   326→	}
   327→
   328→	bDefaultMeshesBackedUp = true;
   329→	UE_LOG(LogWjWorldCosmetic, Log, TEXT("기본 메시 백업 완료"));
   330→}
   331→
   332→void UWjWorldCosmeticComponent::RestoreDefaultMesh(ECosmeticSlot Slot)
   333→{
   334→	if (Slot != ECosmeticSlot::Body)
   335→	{
   336→		return;
   337→	}
   338→
   339→	ACharacter* OwnerCharacter = Cast<ACharacter>(GetOwner());
   340→	if (!OwnerCharacter)
   341→	{
   342→		return;
   343→	}
   344→
   345→	if (const TSoftObjectPtr<USkeletalMesh>* DefaultMesh = DefaultMeshes.Find(Slot))
   346→	{
   347→		if (DefaultMesh->IsValid())
   348→		{
   349→			USkeletalMeshComponent* MeshComp = OwnerCharacter->GetMesh();
   350→			if (MeshComp)
   351→			{
   352→				MeshComp->SetSkeletalMesh(DefaultMesh->Get());
   353→				UE_LOG(LogWjWorldCosmetic, Log, TEXT("기본 메시 복원: 슬롯 %d"), static_cast<int32>(Slot));
   354→			}
   355→		}
   356→	}
   357→}
   358→
   359→void UWjWorldCosmeticComponent::OnLoadoutChangedHandler(ECosmeticSlot Slot, FName ItemId)
   360→{
   361→	// 로컬 플레이어 캐릭터만 처리 (멀티플레이어에서 다른 플레이어 캐릭터 제외)
   362→	APawn* OwnerPawn = Cast<APawn>(GetOwner());
   363→	if (!OwnerPawn)
   364→	{
   365→		return;
   366→	}
   367→
   368→	// 로컬 컨트롤 여부 확인
   369→	if (!OwnerPawn->IsLocallyControlled())
   370→	{
   371→		return;
   372→	}
   373→
   374→	UE_LOG(LogWjWorldCosmetic, Log, TEXT("CosmeticComponent: 로드아웃 변경 감지 - 슬롯 %d, 아이템 %s"),
   375→		static_cast<int32>(Slot), *ItemId.ToString());
   376→
   377→	if (ItemId.IsNone())
   378→	{
   379→		// 아이템 해제
   380→		ClearSlot(Slot);
   381→	}
   382→	else
   383→	{
   384→		// 아이템 장착
   385→		ApplySlot(Slot, ItemId);
   386→	}
   387→}
   388→
   389→FName UWjWorldCosmeticComponent::GetDefaultSocketName(ECosmeticSlot Slot)
   390→{
   391→	switch (Slot)
   392→	{
   393→	case ECosmeticSlot::Head:
   394→		return FName(TEXT("head"));  // 스켈레톤의 head 본/소켓
   395→	case ECosmeticSlot::Body:
   396→		return NAME_None;  // Body는 메시 교체 방식
   397→	case ECosmeticSlot::Back:
   398→		return FName(TEXT("spine_03"));  // 등 부착용
   399→	case ECosmeticSlot::Effect:
   400→		return FName(TEXT("root"));  // 이펙트는 루트
   401→	default:
   402→		return NAME_None;
   403→	}
   404→}
